shaders.source:
struct Uniforms {
  mvp : mat4x4<f32>,
  normalMatrix : mat3x3<f32>,
  emissive : vec3<f32>,
};
@group(0) @binding(0) var<uniform> u : Uniforms;

struct VertexInput {
  @location(0) position : vec3<f32>,
  @location(1) uv : vec2<f32>,
};

struct VertexOutput {
  @builtin(position) position : vec4<f32>,
  @location(0) vUv : vec2<f32>,
};

@vertex
fn vertexMain(in : VertexInput) -> VertexOutput {
  var out : VertexOutput;
  out.vUv = in.uv;
  out.position = (u.mvp * vec4<f32>(in.position, 1.0));
  return out;
}

@fragment
fn fragmentMain(in : VertexOutput) -> @location(0) vec4<f32> {
  let stripe = ((sin((in.vUv.x * 18.0)) * 0.12) + 0.88);
  return vec4<f32>(mix(vec3<f32>(0.025, 0.04, 0.07), u.emissive, stripe), 1.0);
}

shaders.vertex:
#version 300 es
in vec3 position;
in vec2 uv;
uniform mat4 mvp;
uniform mat3 normalMatrix;
uniform vec3 emissive;
out vec2 vUv;

void main() {
  vUv = uv;
  gl_Position = (mvp * vec4(position, 1.0));
}

shaders.fragment:
#version 300 es
precision highp float;
uniform mat4 mvp;
uniform mat3 normalMatrix;
uniform vec3 emissive;
in vec2 vUv;
out vec4 fragColor;

void main() {
  float stripe = ((sin((vUv.x * 18.0)) * 0.12) + 0.88);
  fragColor = vec4(mix(vec3(0.025, 0.04, 0.07), emissive, stripe), 1.0);
}
